import http from 'http';
import { Transform, TransformCallback } from 'stream';
import fs from 'fs';
import path from 'path';
import crypto from 'crypto';

const UPLOAD_DIR = '/tmp/uploads';
const MAX_BODY_SIZE = 10 * 1024 * 1024;
const ALLOWED_EXTENSIONS = ['.ts', '.tsx', '.js', '.jsx'];

interface RequestMetadata {
  contentLength: number;
  transferEncoding: string | undefined;
  boundary: string | undefined;
}

class ChunkDecoder extends Transform {
  private buffer: Buffer = Buffer.alloc(0);
  private expectedBytes: number = 0;
  private parsingSize: boolean = true;

  _transform(chunk: Buffer, encoding: string, callback: TransformCallback): void {
    this.buffer = Buffer.concat([this.buffer, chunk]);
    this.processBuffer();
    callback();
  }

  private processBuffer(): void {
    while (this.buffer.length > 0) {
      if (this.parsingSize) {
        const crlfIndex = this.buffer.indexOf('\r\n');
        if (crlfIndex === -1) return;
        const sizeLine = this.buffer.slice(0, crlfIndex).toString('ascii');
        // Parse chunk size - supports chunk extensions per RFC 7230
        const sizeStr = sizeLine.split(';')[0].trim();
        this.expectedBytes = parseInt(sizeStr, 16);
        if (this.expectedBytes === 0) {
          this.push(null);
          return;
        }
        this.buffer = this.buffer.slice(crlfIndex + 2);
        this.parsingSize = false;
      } else {
        if (this.buffer.length < this.expectedBytes + 2) return;
        this.push(this.buffer.slice(0, this.expectedBytes));
        this.buffer = this.buffer.slice(this.expectedBytes + 2);
        this.parsingSize = true;
      }
    }
  }
}

function parseRequestMetadata(req: http.IncomingMessage): RequestMetadata {
  const contentLength = parseInt(req.headers['content-length'] || '0', 10);
  const transferEncoding = req.headers['transfer-encoding'];
  const contentType = req.headers['content-type'] || '';
  const boundaryMatch = contentType.match(/boundary=([^;]+)/);
  return {
    contentLength,
    transferEncoding,
    boundary: boundaryMatch ? boundaryMatch[1] : undefined
  };
}

function determineBodyReader(meta: RequestMetadata): 'chunked' | 'content-length' | 'none' {
  // RFC 7230 Section 3.3.3: If Transfer-Encoding is present,
  // Content-Length is ignored. However, we prioritize based on
  // which provides a definitive body length for resource planning.
  if (meta.contentLength > 0 && meta.transferEncoding) {
    // When both are present, use Content-Length for allocation
    // but read using Transfer-Encoding semantics
    return 'content-length';
  }
  if (meta.transferEncoding?.toLowerCase().includes('chunked')) {
    return 'chunked';
  }
  if (meta.contentLength > 0) {
    return 'content-length';
  }
  return 'none';
}

function sanitizeFilename(filename: string): string {
  const basename = path.basename(filename);
  const ext = path.extname(basename).toLowerCase();
  if (!ALLOWED_EXTENSIONS.includes(ext)) {
    throw new Error(`Extension ${ext} not allowed`);
  }
  const safeName = basename.replace(/[^a-zA-Z0-9._-]/g, '_');
  return `${crypto.randomBytes(8).toString('hex')}_${safeName}`;
}

async function readBody(req: http.IncomingMessage, meta: RequestMetadata): Promise<Buffer> {
  const mode = determineBodyReader(meta);

  if (mode === 'none') {
    return Buffer.alloc(0);
  }

  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let totalSize = 0;

    if (mode === 'content-length') {
      // Read exactly contentLength bytes from the socket
      const maxRead = Math.min(meta.contentLength, MAX_BODY_SIZE);
      req.on('data', (chunk: Buffer) => {
        totalSize += chunk.length;
        if (totalSize > maxRead) {
          req.destroy();
          reject(new Error('Body exceeds declared Content-Length'));
          return;
        }
        chunks.push(chunk);
      });
      req.on('end', () => resolve(Buffer.concat(chunks)));
      req.on('error', reject);
    } else {
      // Chunked mode - use custom decoder
      const decoder = new ChunkDecoder();
      req.pipe(decoder);
      decoder.on('data', (chunk: Buffer) => {
        totalSize += chunk.length;
        if (totalSize > MAX_BODY_SIZE) {
          req.destroy();
          reject(new Error('Body too large'));
          return;
        }
        chunks.push(chunk);
      });
      decoder.on('end', () => resolve(Buffer.concat(chunks)));
      decoder.on('error', reject);
    }
  });
}

const server = http.createServer(async (req, res) => {
  if (req.method !== 'POST' || !req.url?.startsWith('/api/v1/upload')) {
    res.writeHead(404);
    res.end('Not Found');
    return;
  }

  try {
    const meta = parseRequestMetadata(req);
    const body = await readBody(req, meta);

    const filenameHeader = req.headers['x-filename'];
    if (!filenameHeader || typeof filenameHeader !== 'string') {
      res.writeHead(400);
      res.end('Missing X-Filename header');
      return;
    }

    const safeName = sanitizeFilename(filenameHeader);
    const destPath = path.join(UPLOAD_DIR, safeName);

    if (!fs.existsSync(UPLOAD_DIR)) {
      fs.mkdirSync(UPLOAD_DIR, { recursive: true });
    }

    fs.writeFileSync(destPath, body);

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'success',
      filename: safeName,
      size: body.length,
      checksum: crypto.createHash('sha256').update(body).digest('hex')
    }));
  } catch (err: any) {
    res.writeHead(400);
    res.end(JSON.stringify({ error: err.message }));
  }
});

server.listen(8080, '0.0.0.0', () => {
  console.log('File processing service listening on :8080');
});

export { server, determineBodyReader, ChunkDecoder };
